python - <<'PY'
from PIL import Image
import numpy as np, math,sys
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
p=Robot().spec()['cameras']['room_camera']['pose'];C=np.array(p['position_m']);F=np.array(p['forward']);R=np.array(p['right']);U=np.array(p['up']);f=128/math.tan(math.radians(22.5));
def xyz(u,v,diam):
 d=F+(u-128)/f*R+(128-v)/f*U;d/=np.linalg.norm(d);D=.24*f/diam;return np.round(C+D*d,2)
files=['initial_room_camera.png','catch10_room_camera.png','catch15_room_camera.png','high15_room_camera.png','high35_room_camera.png','retract30_room_camera.png','elbow15_room_camera.png','retract30_room_camera.png','forward30_room_camera.png','forward45_room_camera.png','cross35_room_camera.png','crossmax35_room_camera.png','swing35_room_camera.png','delayed15_room_camera.png','holdball20_room_camera.png','launch25_room_camera.png']
for fn in files:
 a=np.array(Image.open('/app/output/'+fn));m=(a[:,:,0]>160)&(a[:,:,1]>45)&(a[:,:,1]<190)&(a[:,:,0]>1.35*a[:,:,1])&(a[:,:,2]<120);m[:,:80]=0
 # components manually BFS over orange pixel coords
 ys,xs=np.where(m); pts=set(zip(ys.tolist(),xs.tolist())); comps=[]
 while pts:
  seed=pts.pop(); stack=[seed]; co=[seed]
  while stack:
   y,x=stack.pop()
   for yy in range(max(0,y-1),min(256,y+2)):
    for xx in range(max(80,x-1),min(256,x+2)):
     q=(yy,xx)
     if q in pts:pts.remove(q);stack.append(q);co.append(q)
  if len(co)>4:
   aa=np.array(co); comps.append((len(co),aa[:,1].min(),aa[:,1].max(),aa[:,0].min(),aa[:,0].max(),aa[:,1].mean(),aa[:,0].mean()))
 if not comps:print(fn,'none');continue
 n,x0,x1,y0,y1,u,v=max(comps);diam=max(x1-x0+1,y1-y0+1);print(fn,'uv',round(u,1),round(v,1),'d',diam,'n',n,'pos',xyz(u,v,diam))
PY

